<?php
/** Veyra Pro advanced routing, failover, capacity and load balancing. */
function veyra_pro_routing_settings(): array {
    $d=['strategy'=>'priority_weighted','allow_degraded'=>1,'capacity_reserve'=>0,'circuit_failure_threshold'=>3,'circuit_open_seconds'=>300];
    if(!table_exists('routing_settings')) return $d;
    try{$r=db()->query('SELECT * FROM routing_settings WHERE id=1')->fetch();return $r?array_merge($d,$r):$d;}catch(Throwable $e){return $d;}
}
function veyra_pro_save_routing_settings(array $in): array {
    $strategy=strtolower(trim((string)($in['strategy']??'priority_weighted')));if(!in_array($strategy,['priority','weighted','capacity','priority_weighted'],true))$strategy='priority_weighted';
    $q=db()->prepare('INSERT INTO routing_settings (id,strategy,allow_degraded,capacity_reserve,circuit_failure_threshold,circuit_open_seconds) VALUES (1,?,?,?,?,?) ON DUPLICATE KEY UPDATE strategy=VALUES(strategy),allow_degraded=VALUES(allow_degraded),capacity_reserve=VALUES(capacity_reserve),circuit_failure_threshold=VALUES(circuit_failure_threshold),circuit_open_seconds=VALUES(circuit_open_seconds)');
    $q->execute([$strategy,!empty($in['allow_degraded'])?1:0,max(0,min(100000,(int)($in['capacity_reserve']??0))),max(1,min(20,(int)($in['circuit_failure_threshold']??3))),max(30,min(86400,(int)($in['circuit_open_seconds']??300)))]);return veyra_pro_routing_settings();
}
function veyra_pro_provider_route_state(int $providerId): array {
    $d=['provider_id'=>$providerId,'consecutive_failures'=>0,'circuit_state'=>'closed','open_until'=>null];if(!table_exists('provider_route_state'))return $d;
    $q=db()->prepare('SELECT * FROM provider_route_state WHERE provider_id=?');$q->execute([$providerId]);$r=$q->fetch();if(!$r)return $d;if(($r['circuit_state']??'closed')==='open'&&!empty($r['open_until'])&&strtotime((string)$r['open_until'])<=time()){$r['circuit_state']='half_open';}return array_merge($d,$r);
}
function veyra_pro_route_provider_success(int $providerId): void {if(!table_exists('provider_route_state'))return;db()->prepare('INSERT INTO provider_route_state (provider_id,consecutive_failures,circuit_state,last_success_at,last_error) VALUES (?,0,"closed",NOW(),NULL) ON DUPLICATE KEY UPDATE consecutive_failures=0,circuit_state="closed",open_until=NULL,last_success_at=NOW(),last_error=NULL')->execute([$providerId]);}
function veyra_pro_route_provider_failure(int $providerId,string $error): array {
    if(!table_exists('provider_route_state'))return ['opened'=>false];$cfg=veyra_pro_routing_settings();$state=veyra_pro_provider_route_state($providerId);$n=(int)$state['consecutive_failures']+1;$open=$n>=(int)$cfg['circuit_failure_threshold'];$until=$open?date('Y-m-d H:i:s',time()+(int)$cfg['circuit_open_seconds']):null;
    db()->prepare('INSERT INTO provider_route_state (provider_id,consecutive_failures,circuit_state,open_until,last_failure_at,last_error) VALUES (?,?,?, ?,NOW(),?) ON DUPLICATE KEY UPDATE consecutive_failures=VALUES(consecutive_failures),circuit_state=VALUES(circuit_state),open_until=VALUES(open_until),last_failure_at=NOW(),last_error=VALUES(last_error)')->execute([$providerId,$n,$open?'open':'closed',$until,mb_substr($error,0,1000)]);return ['opened'=>$open,'failures'=>$n,'open_until'=>$until];
}
function veyra_pro_provider_capacity(int $providerId,?int $maxClients=null): array {
    $q=db()->prepare("SELECT COUNT(*) FROM service_instances WHERE provider_id=? AND status IN ('active','pending','suspended')");$q->execute([$providerId]);$active=(int)$q->fetchColumn();$max=$maxClients===null?null:max(0,$maxClients);$usedRatio=($max&&$max>0)?min(1,$active/$max):0.0;return ['active'=>$active,'max'=>$max,'free'=>$max===null?null:max(0,$max-$active),'utilization'=>$usedRatio];
}
function veyra_pro_route_candidates(int $planId,?array $mapIds=null): array {
    $maps=veyra_plan_provider_maps($planId);$wanted=$mapIds?array_flip(array_map('intval',$mapIds)):null;$cfg=veyra_pro_routing_settings();$out=[];
    foreach($maps as $m){if(empty($m['is_active'])||empty($m['provider_active']))continue;if($wanted!==null&&!isset($wanted[(int)$m['id']]))continue;$pid=(int)$m['provider_id'];$p=veyra_provider($pid);if(!$p)continue;$driverMeta=VeyraProviderRegistry::supportedDrivers()[(string)$p['driver']]??[];if(empty($driverMeta['live']))continue;$econ=function_exists('veyra_provider_economics')?veyra_provider_economics($pid):[];if(!empty($econ['maintenance_mode']))continue;$state=veyra_pro_provider_route_state($pid);if(($state['circuit_state']??'closed')==='open'&&!empty($state['open_until'])&&strtotime((string)$state['open_until'])>time())continue;$health=strtolower((string)($p['last_health_status']??$p['status']??'unknown'));if($health==='offline')continue;if($health==='degraded'&&empty($cfg['allow_degraded']))continue;$cap=veyra_pro_provider_capacity($pid,$p['max_clients']===null?null:(int)$p['max_clients']);$reserve=(int)$cfg['capacity_reserve'];if($cap['max']!==null&&$cap['free']<=$reserve)continue;if($cap['max']!==null&&!empty($econ['soft_capacity_percent'])&&($cap['utilization']*100)>=(int)$econ['soft_capacity_percent'])continue;$m['provider']=$p;$m['route_state']=$state;$m['capacity']=$cap;$m['health']=$health;$m['economics']=$econ;$out[]=$m;}
    return $out;
}
function veyra_pro_weighted_pick(array $items,callable $weightFn): ?array {if(!$items)return null;$sum=0;$weights=[];foreach($items as $k=>$x){$w=max(1,(int)round($weightFn($x)));$weights[$k]=$w;$sum+=$w;}$r=random_int(1,max(1,$sum));foreach($items as $k=>$x){$r-=$weights[$k];if($r<=0)return$x;}return end($items)?:null;}
function veyra_pro_route_order(array $order,array $plan,?array $mapIds=null): array {
    $cfg=veyra_pro_routing_settings();$c=veyra_pro_route_candidates((int)$plan['id'],$mapIds);if(!$c)throw new RuntimeException('NO_HEALTHY_ROUTE');$strategy=(string)$cfg['strategy'];$ordered=[];
    if($strategy==='capacity'){usort($c,fn($a,$b)=>[$a['capacity']['utilization'],(int)$a['priority'],(int)$a['id']]<=>[$b['capacity']['utilization'],(int)$b['priority'],(int)$b['id']]);$ordered=$c;}
    elseif($strategy==='priority'){usort($c,fn($a,$b)=>[(int)$a['priority'],$a['capacity']['utilization'],(int)$a['id']]<=>[(int)$b['priority'],$b['capacity']['utilization'],(int)$b['id']]);$ordered=$c;}
    else {if($strategy==='priority_weighted'){$min=min(array_map(fn($x)=>(int)$x['priority'],$c));$pool=array_values(array_filter($c,fn($x)=>(int)$x['priority']===$min));}else{$pool=$c;}$first=veyra_pro_weighted_pick($pool,function($x){$mapW=max(1,(int)($x['weight']??100));$providerW=max(1,(int)($x['provider']['weight']??100));$freeFactor=$x['capacity']['max']===null?1.0:max(.05,1.0-(float)$x['capacity']['utilization']);$healthFactor=$x['health']==='degraded'?.25:1.0;return $mapW*$providerW*$freeFactor*$healthFactor;});if($first){$ordered[]=$first;$rest=array_values(array_filter($c,fn($x)=>(int)$x['id']!==(int)$first['id']));usort($rest,fn($a,$b)=>[(int)$a['priority'],$a['capacity']['utilization'],-(int)$a['weight']]<=>[(int)$b['priority'],$b['capacity']['utilization'],-(int)$b['weight']]);$ordered=array_merge($ordered,$rest);}else $ordered=$c;}
    $decision=['strategy'=>$strategy,'candidate_count'=>count($ordered),'candidates'=>array_map(fn($m)=>['map_id'=>(int)$m['id'],'provider_id'=>(int)$m['provider_id'],'target'=>(string)$m['remote_target_id'],'priority'=>(int)$m['priority'],'weight'=>(int)$m['weight'],'health'=>$m['health'],'capacity'=>$m['capacity']],$ordered)];return ['ordered'=>$ordered,'decision'=>$decision];
}
function veyra_pro_record_route_decision(array $order,array $plan,int $serviceId,int $jobId,array $decision): int {if(!table_exists('routing_decisions'))return 0;$q=db()->prepare('INSERT INTO routing_decisions (order_id,user_service_id,job_id,service_plan_id,strategy,decision_json) VALUES (?,?,?,?,?,?)');$q->execute([(int)$order['id'],$serviceId,$jobId,(int)$plan['id'],(string)$decision['strategy'],json_encode($decision,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);return(int)db()->lastInsertId();}
function veyra_pro_record_route_attempt(int $decisionId,int $jobId,array $m,string $outcome,?string $error=null,int $latency=0): void {if(!table_exists('routing_attempts'))return;db()->prepare('INSERT INTO routing_attempts (routing_decision_id,job_id,map_id,provider_id,remote_target_id,outcome,error_message,latency_ms) VALUES (?,?,?,?,?,?,?,?)')->execute([$decisionId?:null,$jobId,(int)$m['id'],(int)$m['provider_id'],(string)$m['remote_target_id'],$outcome,$error?mb_substr($error,0,1000):null,$latency?:null]);}
function veyra_pro_routing_dashboard(): array {
    $out=['settings'=>veyra_pro_routing_settings(),'providers'=>[],'recent_decisions'=>[],'recent_attempts'=>[],'stats'=>['open_circuits'=>0,'full_providers'=>0]];
    foreach(veyra_providers(false) as $p){$cap=veyra_pro_provider_capacity((int)$p['id'],$p['max_clients']===null?null:(int)$p['max_clients']);$state=veyra_pro_provider_route_state((int)$p['id']);if(($state['circuit_state']??'closed')==='open'&&!empty($state['open_until'])&&strtotime((string)$state['open_until'])>time())$out['stats']['open_circuits']++;if($cap['max']!==null&&$cap['free']<=0)$out['stats']['full_providers']++;$out['providers'][]=['id'=>(int)$p['id'],'name'=>$p['name'],'health'=>$p['last_health_status']??$p['status'],'capacity'=>$cap,'route_state'=>$state];}
    if(table_exists('routing_decisions'))$out['recent_decisions']=db()->query('SELECT rd.*,sp.name selected_provider_name FROM routing_decisions rd LEFT JOIN service_providers sp ON sp.id=rd.selected_provider_id ORDER BY rd.id DESC LIMIT 30')->fetchAll()?:[];
    if(table_exists('routing_attempts'))$out['recent_attempts']=db()->query('SELECT ra.*,sp.name provider_name FROM routing_attempts ra LEFT JOIN service_providers sp ON sp.id=ra.provider_id ORDER BY ra.id DESC LIMIT 50')->fetchAll()?:[];return$out;
}
